// Get member_id passed into this sub-workflow
const memberId =
  $('When Executed by Another Workflow').first().json.member_id;

// Parsed members.json from the previous node
const members = $input.first().json.data;

// Validate input
if (!memberId) {
  return [
    {
      json: {
        tool: "ELIGIBILITY",
        status: "INVALID_INPUT",
        member_id: null,
        data: null,
        error: "member_id is required"
      }
    }
  ];
}

// Find requested member
const member = members.find(
  (record) => record.member_id === memberId
);

// Member not found
if (!member) {
  return [
    {
      json: {
        tool: "ELIGIBILITY",
        status: "NOT_FOUND",
        member_id: memberId,
        data: null,
        error: "Member not found"
      }
    }
  ];
}

// Return only fields useful to servicing
return [
  {
    json: {
      tool: "ELIGIBILITY",
      status: "SUCCESS",
      member_id: member.member_id,
      data: {
        name: member.name,
        plan_id: member.plan_id,
        plan_name: member.plan_name,
        coverage_status: member.coverage_status,
        coverage_effective_date: member.coverage_effective_date,
        coverage_termination_date:
          member.coverage_termination_date ?? null,
        enrollment_status: member.enrollment_status,
        enrollment_effective_date:
          member.enrollment_effective_date ?? null,
        eligibility_last_synced_date:
          member.eligibility_last_synced_date ?? null
      },
      error: null
    }
  }
];
